const input = $input.first().json;
const job = input.job ?? input;
if (job.kind !== 'publish' || !job.id || !job.client_id || !job.target_id || !job.leaseToken) throw new Error('Contrato publish v1 invalido');
const requested = job.payload?.publication;
if (!requested?.desiredScheduledAt || Number.isNaN(Date.parse(requested.desiredScheduledAt))) throw new Error('desiredScheduledAt ISO-8601 es obligatorio; no se usa now + 5 minutos');
return [{ json: { schemaVersion: 1, job } }];

const job = $('Validar trabajo y fecha').first().json.job;
const context = $input.first().json;
const requested = job.payload.publication;
const provider = job.payload?.providerResult;
if (!provider?.postId) throw new Error('Inserta el nodo Postiz del workflow original y entrega payload.providerResult.postId');
const account = (context.accounts ?? []).find((item) => item.id === requested.accountId && item.provider === 'postiz');
if (!account) throw new Error('La cuenta Postiz no pertenece al contexto del cliente');
const publication = { status: 'scheduled', confirmedScheduledAt: requested.desiredScheduledAt, postizPostId: String(provider.postId), providerPostId: provider.providerPostId ? String(provider.providerPostId) : null, externalUrl: provider.externalUrl ?? null, publishedAt: null, errorCode: null, errorMessage: null };
const event = { schemaVersion: 1, clientId: job.client_id, entityType: 'publication', entityId: job.target_id, eventType: 'postiz.scheduled', sourceEventId: `postiz:${account.id}:${provider.postId}:scheduled`, occurredAt: provider.occurredAt ?? new Date().toISOString(), publicationStatus: 'scheduled', payload: { accountId: account.id, desiredScheduledAt: requested.desiredScheduledAt, confirmedScheduledAt: requested.desiredScheduledAt, postizPostId: String(provider.postId), workflowVersion: 1 } };
return [{ json: { schemaVersion: 1, clientId: job.client_id, status: 'succeeded', publication, event, result: { workflowVersion: 1, state: 'scheduled' }, leaseToken: job.leaseToken, jobId: job.id } }];
